#!/usr/bin/env node
/**
 * ReCiterDB's pub_type_map seed must agree with src/lib/pubTypes.ts (plan 5c, decision D7).
 *
 * The reporting stored procedure can't import pubTypes.ts, so ReCiterDB copies its CROSSREF,
 * OPENALEX and SCOPUS maps (and the type groups) into setup/seed_pub_type_map.sql, generated by
 * update/pub_type_map_seed.py, plus a RECITER map for the publicationTypeCanonical values on
 * PubMed rows. This script checks that every key the seed carries maps exactly as pubTypes.ts maps
 * it, that no pubTypes.ts key is missing from the seed, and that every RECITER row names one of
 * the 18 types in its right group.
 *
 * Run: node scripts/check-pub-type-map.mjs <path to ReCiterDB>/setup/seed_pub_type_map.sql
 *      (or set PUB_TYPE_MAP_SEED). No DB, no build.
 */

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { PUB_TYPES, typeGroupOf, mapSourceType, sourceTypeKeys } from "../src/lib/pubTypes.ts";

const seedPath = process.argv[2] || process.env.PUB_TYPE_MAP_SEED;
if (!seedPath) {
  console.error("usage: node scripts/check-pub-type-map.mjs <ReCiterDB>/setup/seed_pub_type_map.sql");
  process.exit(2);
}

// ('SOURCE', 'key', 'Type' | NULL, 'group' | NULL, 0 | 1)
const sqlValue = (v) => (v === "NULL" ? null : /^'.*'$/.test(v) ? v.slice(1, -1).replace(/''/g, "'") : Number(v));
const parseSeed = (sql) => {
  const insert = sql.match(/INSERT INTO pub_type_map \(source, source_type, pub_type, pub_type_group, counted\) VALUES([\s\S]*?);/);
  assert.ok(insert, "seed has no INSERT INTO pub_type_map (source, source_type, pub_type, pub_type_group, counted) VALUES …;");
  const rows = [];
  const re = /\(\s*('(?:[^']|'')*'|NULL)\s*,\s*('(?:[^']|'')*'|NULL)\s*,\s*('(?:[^']|'')*'|NULL)\s*,\s*('(?:[^']|'')*'|NULL)\s*,\s*(\d+)\s*\)/g;
  for (const m of insert[1].matchAll(re)) {
    const [source, key, type, group, counted] = m.slice(1).map(sqlValue);
    rows.push({ source, key, type, group, counted });
  }
  return rows;
};

const norm = (t) => String(t || "").trim().toLowerCase().replace(/[\s_]+/g, "-");

export const checkSeed = (sql) => {
  const rows = parseSeed(sql);
  assert.ok(rows.length > 0, "seed has no rows");
  const problems = [];
  const seen = new Set();
  for (const r of rows) {
    const id = `${r.source}:${r.key}`;
    if (seen.has(id)) problems.push(`${id}: duplicate key`);
    seen.add(id);
    if (norm(r.key) !== r.key) problems.push(`${id}: key is not normalized (want ${norm(r.key)})`);
    if (r.type !== null && !PUB_TYPES.includes(r.type)) problems.push(`${id}: ${r.type} is not one of the 18 types`);
    const wantGroup = r.type === null ? null : typeGroupOf(r.type) ?? null;
    if (r.group !== wantGroup) problems.push(`${id}: group ${r.group}, pubTypes.ts says ${wantGroup}`);
    if (r.counted !== (r.type === null ? 0 : 1)) problems.push(`${id}: counted ${r.counted} with type ${r.type}`);
    if (r.source === "RECITER") continue;
    const m = mapSourceType(r.source.toLowerCase(), r.key);
    if (m.disposition === "unmapped") problems.push(`${id}: in the seed but not in pubTypes.ts`);
    else if ((m.type ?? null) !== r.type) problems.push(`${id}: seed says ${r.type}, pubTypes.ts says ${m.type ?? null}`);
  }
  for (const source of ["crossref", "openalex", "scopus"]) {
    for (const key of sourceTypeKeys(source)) {
      if (!seen.has(`${source.toUpperCase()}:${key}`)) problems.push(`${source.toUpperCase()}:${key}: in pubTypes.ts but not in the seed`);
    }
  }
  const sources = new Set(rows.map((r) => r.source));
  for (const s of ["CROSSREF", "OPENALEX", "SCOPUS", "RECITER"]) if (!sources.has(s)) problems.push(`${s}: no rows in the seed`);
  return { rows, problems };
};

// Self-checks on a tiny seed, so a parser regression can't pass silently.
{
  const ok = (rows) => `INSERT INTO pub_type_map (source, source_type, pub_type, pub_type_group, counted) VALUES\n${rows.join(",\n")};`;
  const bad = checkSeed(ok([
    "('SCOPUS', 'article', 'Review', 'journal', 1)",
    "('SCOPUS', 'Short Survey', 'Review', 'journal', 1)",
    "('OPENALEX', 'erratum', NULL, NULL, 1)",
    "('CROSSREF', 'book', 'Book', 'journal', 1)",
    "('RECITER', 'case-report', 'Case Report', 'journal', 1)",
  ]));
  const text = bad.problems.join("\n");
  for (const want of [
    "SCOPUS:article: seed says Review, pubTypes.ts says Academic Article",
    "SCOPUS:Short Survey: key is not normalized",
    "OPENALEX:erratum: counted 1",
    "CROSSREF:book: group journal, pubTypes.ts says book",
    "RECITER:case-report: Case Report is not one of the 18 types",
    "SCOPUS:review: in pubTypes.ts but not in the seed",
  ]) assert.ok(text.includes(want), `self-check: expected a problem "${want}" in:\n${text}`);
}

const { rows, problems } = checkSeed(readFileSync(seedPath, "utf8"));
if (problems.length) {
  console.error(`check-pub-type-map: ${problems.length} problem(s) in ${seedPath}`);
  for (const p of problems) console.error(`  - ${p}`);
  console.error("Fix pubTypes.ts or regenerate the seed: python3 update/pub_type_map_seed.py --pubtypes <PM>/src/lib/pubTypes.ts --write");
  process.exit(1);
}
const bySource = rows.reduce((acc, r) => ((acc[r.source] = (acc[r.source] || 0) + 1), acc), {});
console.log(`check-pub-type-map: OK (${rows.length} keys: ${Object.entries(bySource).map(([k, v]) => `${k} ${v}`).join(", ")})`);
